WITH parsed AS (SELECT id, service, latency_ms, status_code, payload_json, context, COALESCE(context['version'], 'direct') AS version_or_default, GET_JSON_OBJECT(payload_json, '$.duration') AS duration_text, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration AS duration_sec, COALESCE(context['trace'], 'unknown') AS trace_or_default FROM app_logs WHERE status_code >= 376) SELECT *, LEAD(duration_sec) OVER (PARTITION BY service ORDER BY status_code, id) AS next_duration_sec, LAG(latency_ms) OVER (PARTITION BY service ORDER BY status_code, id) AS prev_latency_ms, ROW_NUMBER() OVER (PARTITION BY service ORDER BY status_code, id) AS seq_no FROM parsed
